  NO.lang = 'zh';

  NO.setLang = function (lang) {
    if (!NO.I18N[lang]) lang = 'en';
    NO.lang = lang;
    document.documentElement.lang = lang === 'zh' ? 'zh-CN' : lang;
  };

  NO.t = function (key, vars, lang) {
    const l = lang || NO.lang || 'zh';
    let s = (NO.I18N[l] && NO.I18N[l][key]);
    if (s == null) s = (NO.I18N.en && NO.I18N.en[key]);
    if (s == null) s = (NO.I18N.zh && NO.I18N.zh[key]);
    if (s == null) return key;
    if (vars) {
      for (const k in vars) s = s.replace(new RegExp('\\{' + k + '\\}', 'g'), vars[k]);
    }
    return s;
  };

  NO.L = function (obj, lang) {
    if (obj == null) return '';
    if (typeof obj === 'string') return obj;
    const l = lang || NO.lang || 'zh';
    return obj[l] != null ? obj[l] : (obj.en != null ? obj.en : (obj.zh != null ? obj.zh : ''));
  };

